        "event_id": "lite_evt_00062",
        "explanation": "未经处方来源确认即改变当日给药次数，破坏用药责任链。",
        "quote": "今天不用再滴第四次"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00106",
        "explanation": "医生把资料中未确认的早期和两周复查节点表述为确定且必须执行的时间线。",
        "quote": "术后2周是常规复查"
      }
    ],
    "continuity_memory_focus": [
